import numpy as np,json
p='/app/runs/initial/'
m=json.load(open(p+'meta.json'))
d=np.load(p+'depth_egoview.npy')
print('depth',d.shape,d.dtype, np.nanmin(d), np.nanmax(d))
cam=m['cameras']['egoview']; K=np.array(cam['intrinsic_cv']); T=np.array(cam['cam2world_gl']);
def world(u,v):
 z=float(d[v,u]); ray=np.array([(u-K[0,2])/K[0,0],-(v-K[1,2])/K[1,1],-1.])*z
 return z,(T[:3,:3]@ray+T[:3,3]).round(4)
for xy in [(95,169),(94,169),(95,165),(95,175),(217,169),(217,165),(217,175),(138,155),(228,191),(250,190),(63,190),(240,190)]:
 print(xy,world(*xy))
lay=m['proprio']['layout']; v=np.array(m['proprio']['now']); dct=dict(zip(lay,v));
print('eef world',*[dct['eef_'+s+'_'+axis] for s in ['left','right'] for axis in ['x','y','z']])
