import numpy as np,json
p='/app/runs/initial/'
m=json.load(open(p+'meta.json'))
d=np.load(p+'depth_egoview.npy')[0]
cam=m['cameras']['egoview']; K=np.array(cam['intrinsic_cv']); T=np.array(cam['cam2world_gl']);
def world(u,v):
 z=float(d[v,u]); ray=np.array([(u-K[0,2])/K[0,0],-(v-K[1,2])/K[1,1],-1.])*z
 return z,(T[:3,:3]@ray+T[:3,3]).round(4)
for xy in [(95,169),(95,165),(95,175),(217,169),(217,165),(217,175),(138,155),(228,191),(250,190),(63,190),(240,190)]: print(xy,world(*xy))
lay=m['proprio']['layout']; v=np.array(m['proprio']['now']); dct=dict(zip(lay,v));
print('eef left',*[dct[f'eef_left_{axis}'] for axis in ['x','y','z']])
print('eef right',*[dct[f'eef_right_{axis}'] for axis in ['x','y','z']])
