import json,numpy as np
p='/app/runs/controller/1790956825225_move_right/meta.json'; m=json.load(open(p));
for cam in ['egoview','robot0_eye_in_right_hand']:
 c=m['cameras'][cam]; T=np.array(c['cam2world_gl']); K=np.array(c['intrinsic_cv']);
 for name,xyz in [('right',[2.781668,-1.832503,1.167803]),('left',[2.404718,-1.926922,1.030765])]:
  q=np.linalg.inv(T)@np.r_[xyz,1]; x,y,z=q[:3]; u=K[0,0]*x/-z+K[0,2]; v=K[1,1]*(-y)/-z+K[1,2]; print(cam,name,'cam',q[:3].round(3),'uv',round(u,1),round(v,1))
